const std=@import("std");const h=@import("machine.zig");const F=h.Fixture;const c=h.c;const util=@import("cga_crtc.zig");
fn time(f:*F,q:u64,frac:u32)!void{util.word(f,try f.symbol("dos64_pit_phase"),@truncate(q));const t=try f.symbol("dos64_pit_total");for(0..4)|i|f.poke(t+@as(u16,@intCast(i)),@truncate(q>>@as(u6,@intCast(16+i*8))));const r=try f.symbol("dos64_pit_fraction");for(0..3)|i|f.poke(r+@as(u16,@intCast(i)),@truncate(frac>>@as(u5,@intCast(i*8))));f.poke(try f.symbol("dos64_pit_ready"),1);f.poke(try f.symbol("dos64_pit_error"),0);f.poke(try f.symbol("dos64_pit_poll_error"),0);}
fn text()!F{var f=try util.init();errdefer f.deinit();f.poke(try f.symbol("dos64_cache_limit"),32);_=try f.call("dos64_cache_init",50000);_=try f.call("dos64_bios_init",40000000);_=try f.call("dos64_cache_flush",2000000);try std.testing.expectEqual(@as(u8,0),(try f.call("dos64_cold_release",10000)).p&1);f.poke(try f.symbol("dos64_cache_limit"),2);_=try f.call("dos64_cache_init",50000);return f;}
fn sample(f:*F)!void{try std.testing.expectEqual(@as(u8,0),(try f.call("dos64_cga_cursor_sample",2000000)).p&1);}
fn row(f:*F,n:u8)!void{const r=try f.symbol("dos64_render_text_request");f.poke(r,n);f.poke(r+1,1);try std.testing.expectEqual(@as(u8,0),(try f.call("dos64_overlay_render_text_row",2000000)).p&1);try std.testing.expectEqual(@as(u8,40),f.peek(r+2));}

test "nativeCGA hardwarecursor addsforeground underline to actual complete40column bitmap and preserves guest source"{
 var f=try text();defer f.deinit();try util.video(&f,1,0,0,0);try time(&f,0,0);
 // Same executable is a missing-feature control on accepted4cc and the later
 // candidate: old image has no phase-sampler API, hence no hidden native patch.
 if(f.symbols.get("dos64_cga_cursor_sample")!=null)try sample(&f);
 for(0..25)|y|try row(&f,@intCast(y));
 for(0..8000)|i|try std.testing.expectEqual(@as(u8,if(i==6 or i==7)255 else 0),f.peek(0x6000+@as(u16,@intCast(i))));
 for(0..1000)|i|try std.testing.expectEqual(@as(u8,0xf0),f.peek(0x4000+@as(u16,@intCast(i))));try std.testing.expectEqual(@as(u8,0x20),try util.busRead(&f,0xb8000));try std.testing.expectEqual(@as(u8,7),try util.busRead(&f,0xb8001));try std.testing.expectEqual(@as(u8,0),try util.busRead(&f,0x450));try std.testing.expectEqual(@as(u8,0),try util.busRead(&f,0x451));
}
fn cursor(f:*F,address:u16,start:u8,end:u8)!void{_=try util.io(f,false,0x3d4,1,14|(@as(u16,@truncate(address>>8))<<8),true);_=try util.io(f,false,0x3d4,1,15|(@as(u16,@truncate(address))<<8),true);_=try util.io(f,false,0x3d4,1,10|(@as(u16,start)<<8),true);_=try util.io(f,false,0x3d4,1,11|(@as(u16,end)<<8),true);}
fn whole(f:*F,cols:usize,pos:?usize,start:usize,end:usize)!void{for(0..25)|y|try row(f,@intCast(y));for(0..1000)|cell|{try std.testing.expectEqual(@as(u8,0xf0),f.peek(0x4000+@as(u16,@intCast(cell))));for(0..8)|y|{const bit:u8=if(pos)|p|if(p/cols==cell/40 and p%cols/(cols/40)==cell%40 and y>=start and y<=end)if(cols==40)255 else if(p%2==0)240 else 15 else 0 else 0;try std.testing.expectEqual(bit,f.peek(0x6000+@as(u16,@intCast(cell*8+y))));}}}

test "actual48bit divider retains full quotient across random maximum and every field phase without portreads overwriting sampled frame"{
 var f=try util.init();defer f.deinit();try util.video(&f,3,0,0,0);var seed:u64=0x123456789abc;const at=try f.symbol("cga_time");for(0..1100)|i|{seed=seed*%6364136223846793005+%1442695040888963407;const q:u64=if(i<256)@as(u64,i)*19912+19911 else if(i==256)0xffffffffffff else seed&0xffffffffffff;try time(&f,q,@intCast(seed%451572));try sample(&f);var quotient:u64=0;for(0..6)|n|quotient|=@as(u64,f.peek(at+@as(u16,@intCast(n))))<<@as(u6,@intCast(n*8));try std.testing.expectEqual(q/19912,quotient);try std.testing.expectEqual(@as(u8,@truncate(q/19912)),f.peek(try f.symbol("dos64_cursor_field_phase")));try std.testing.expectEqual(@as(u8,0xa5),f.peek(try f.symbol("dos64_cursor_phase_valid")));try time(&f,q+%19912,0);_=try util.io(&f,true,0x3da,0,0x55aa,true);try std.testing.expectEqual(@as(u8,@truncate(q/19912)),f.peek(try f.symbol("dos64_cursor_field_phase")));}
}

test "hardware cursor full40and80 bitmap oracle honors every textmode activepage address halfcell offpage and14bit nonalias"{
 var f=try text();defer f.deinit();for(0..4)|mode|{const cols:usize=if(mode<2)40 else 80;try util.video(&f,@intCast(mode),0,0,0);const page:u8=if(cols==40)7 else 3;try util.video(&f,0x0500|@as(u16,page),0,0,0);const base:u16=@as(u16,page)*@as(u16,if(cols==40)1024 else 2048);for([_]usize{0,1,cols-1,cols,24*cols+cols-1})|pos|{try cursor(&f,base+@as(u16,@intCast(pos)),2,5);try time(&f,0,0);try sample(&f);try whole(&f,cols,pos,2,5);try std.testing.expectEqual(@as(u8,0),try util.busRead(&f,0x450+@as(u32,page)*2));try std.testing.expectEqual(@as(u8,0),try util.busRead(&f,0x451+@as(u32,page)*2));}for([_]u16{base+@as(u16,@intCast(cols*25)),base^0x2000})|address|{try cursor(&f,address,0,7);try sample(&f);try whole(&f,cols,null,0,7);}}
}

test "CGA external16field gate and original6845 nonblink hidden16on32on modes compose at field boundaries"{
 var f=try text();defer f.deinit();try util.video(&f,3,0,0,0);for([_]u8{0,0x20,0x40,0x60})|mode|{try cursor(&f,1,mode|6,7);for([_]u64{0,7,8,15,16,23,24,31,32,39,40,47,48,63,64,255,256})|field|{try time(&f,field*19912,0);try sample(&f);const on=mode!=0x20 and field&8==0 and (mode!=0x40 or field&16==0) and (mode!=0x60 or field&32==0);try row(&f,0);for(0..320)|i|try std.testing.expectEqual(@as(u8,if(on and (i==6 or i==7))15 else 0),f.peek(0x6000+@as(u16,@intCast(i))));}}
}

test "cursor ORs foreground after hidden attribute glyph preserves source and honors video blanking and clipped shape"{
 var f=try text();defer f.deinit();try util.video(&f,1,0,0,0);try util.busWrite(&f,0xb8000,65);try util.busWrite(&f,0xb8001,0x87);for(0..8)|i|f.poke(0x4800+65*8+@as(u16,@intCast(i)),0x81);try cursor(&f,0,3,31);try time(&f,0,0);try sample(&f);const r=try f.symbol("dos64_render_text_request");f.poke(r,0);f.poke(r+1,0);try std.testing.expectEqual(@as(u8,0),(try f.call("dos64_overlay_render_text_row",2000000)).p&1);for(0..320)|i|try std.testing.expectEqual(@as(u8,if(i>=3 and i<8)255 else 0),f.peek(0x6000+@as(u16,@intCast(i))));try std.testing.expectEqual(@as(u8,0xf0),f.peek(0x4000));_=try util.io(&f,false,0x3d8,0,0x20,true);try row(&f,0);for(0..40)|i|try std.testing.expectEqual(@as(u8,0),f.peek(0x4000+@as(u16,@intCast(i))));try std.testing.expectEqual(@as(u8,65),try util.busRead(&f,0xb8000));try std.testing.expectEqual(@as(u8,0x87),try util.busRead(&f,0xb8001));try cursor(&f,0,9,31);try sample(&f);try row(&f,0);try std.testing.expectEqual(@as(u8,0x81),f.peek(0x6000));
}

test "stale sample owner busy clock and originaloverlay failures retain old phase reject render before every output byte"{
 var f=try text();defer f.deinit();try util.video(&f,3,0,0,0);try time(&f,19912*17,0);try sample(&f);const phase=try f.symbol("dos64_cursor_field_phase");const valid=try f.symbol("dos64_cursor_phase_valid");for(0..4)|kind|{if(kind==0)f.poke(try f.symbol("hdb_extension_ready"),0);if(kind==1)try util.acquire(&f,4);if(kind==2)f.poke(try f.symbol("dos64_pit_poll_error"),8);if(kind==3)f.poke(try f.symbol("dos64_pit_fraction")+2,255);try std.testing.expectEqual(@as(u8,1),(try f.call("dos64_cga_cursor_sample",100000)).p&1);try std.testing.expectEqual(@as(u8,17),f.peek(phase));try std.testing.expectEqual(@as(u8,255),f.peek(valid));if(kind==1)try util.release(&f);f.poke(try f.symbol("hdb_extension_ready"),0xa5);try time(&f,19912*17,0);for(0..8000)|i|f.poke(0x6000+@as(u16,@intCast(i)),0x96);for(0..1000)|i|f.poke(0x4000+@as(u16,@intCast(i)),0x69);const r=try f.symbol("dos64_render_text_request");f.poke(r,0);f.poke(r+1,1);try std.testing.expectEqual(@as(u8,1),(try f.call("dos64_overlay_render_text_row",2000000)).p&1);try std.testing.expectEqual(@as(u8,3),f.peek(r+4));for(0..8000)|i|try std.testing.expectEqual(@as(u8,0x96),f.peek(0x6000+@as(u16,@intCast(i))));for(0..1000)|i|try std.testing.expectEqual(@as(u8,0x69),f.peek(0x4000+@as(u16,@intCast(i))));try sample(&f);}
 try util.acquire(&f,4);try util.release(&f);const entry=try f.symbol("dos64_pit_init");const target=try f.symbol("dos64_cga_cursor_sample");f.poke(entry,0x20);f.poke(entry+1,@truncate(target));f.poke(entry+2,@truncate(target>>8));f.poke(entry+3,0x60);try std.testing.expectEqual(@as(u8,1),(try f.call("dos64_pit_init",100000)).p&1);try std.testing.expectEqual(@as(u8,4),f.peek(try f.symbol("dos64_overlay_current")));try std.testing.expectEqual(@as(u8,0x20),f.peek(entry));try std.testing.expectEqual(@as(u8,255),f.peek(valid));
}

test "native presenter samples once at frame rowzero freezes full frame and propagates truthful stale failure"{
 var f=try text();defer f.deinit();try util.video(&f,3,0,0,0);f.poke(try f.symbol("n_present_mode"),3);f.poke(try f.symbol("n_row"),0);try time(&f,0,0);try std.testing.expectEqual(@as(u8,0),(try f.call("n_present",2000000)).p&1);try time(&f,8*19912,0);for(1..25)|_|try std.testing.expectEqual(@as(u8,0),(try f.call("n_present",2000000)).p&1);try std.testing.expectEqual(@as(u8,0),f.peek(try f.symbol("dos64_cursor_field_phase")));try std.testing.expectEqual(@as(u8,0),(try f.call("n_present",2000000)).p&1);try std.testing.expectEqual(@as(u8,8),f.peek(try f.symbol("dos64_cursor_field_phase")));f.poke(try f.symbol("n_row"),0);f.poke(try f.symbol("dos64_pit_poll_error"),8);try std.testing.expectEqual(@as(u8,1),(try f.call("n_present",2000000)).p&1);try std.testing.expectEqual(@as(u8,255),f.peek(try f.symbol("dos64_cursor_phase_valid")));try std.testing.expectEqual(@as(u8,3),f.peek((try f.symbol("dos64_render_text_request"))+4));
}
fn capture(f:*F,name:[]const u8,blink:u8)!void{var bytes:[28735]u8=undefined;var n:usize=0;for(0..256)|i|{bytes[n]=try util.busRead(f,0x400+@as(u32,@intCast(i)));n+=1;}for(0..16384)|i|{bytes[n]=try util.busRead(f,0xb8000+@as(u32,@intCast(i)));n+=1;}for([_]struct{at:u16,len:usize}{.{.at=0x4400,.len=1024},.{.at=0x4800,.len=2048}})|part|for(0..part.len)|i|{bytes[n]=f.peek(part.at+@as(u16,@intCast(i)));n+=1;};const rr=try f.symbol("dos64_cga_registers");for(0..18)|i|{bytes[n]=f.peek(rr+@as(u16,@intCast(i)));n+=1;}for([_] []const u8{"dos64_cga_control","dos64_cga_control_valid","dos64_cursor_phase_valid","dos64_cursor_field_phase"})|symbol|{bytes[n]=f.peek(try f.symbol(symbol));n+=1;}bytes[n]=blink;n+=1;for(0..8000)|i|{bytes[n]=f.peek(0x6000+@as(u16,@intCast(i)));n+=1;}for(0..1000)|i|{bytes[n]=f.peek(0x4000+@as(u16,@intCast(i)));n+=1;}try std.testing.expectEqual(bytes.len,n);const path=try std.fmt.allocPrint(std.testing.allocator,"build/cursor-capture-{s}.bin",.{name});defer std.testing.allocator.free(path);try std.Io.Dir.cwd().writeFile(std.Options.debug_io,.{.sub_path=path,.data=&bytes});}

test "complete captured40and80 actual bitmap matrix agree with separately executed pure host oracle including glyphs attributes pages and halfcursor"{
 var f=try text();defer f.deinit();for([_]u16{1,3})|mode|{try util.video(&f,mode,0,0,0);try util.video(&f,0x0501,0,0,0);const cols:usize=if(mode==1)40 else 80;const page:u32=if(cols==40)2048 else 4096;for(0..cols*25)|i|{try util.busWrite(&f,0xb8000+page+@as(u32,@intCast(i*2)),@truncate(i*17+65));try util.busWrite(&f,0xb8001+page+@as(u32,@intCast(i*2)),@truncate(i*37+7));}try cursor(&f,@as(u16,@intCast(page/2+cols*12+3)),4,6);try time(&f,0,451571);try sample(&f);const r=try f.symbol("dos64_render_text_request");for(0..25)|y|{f.poke(r,@intCast(y));f.poke(r+1,0);try std.testing.expectEqual(@as(u8,0),(try f.call("dos64_overlay_render_text_row",2000000)).p&1);}try capture(&f,if(cols==40)"40"else "80",0);_=try util.io(&f,false,0x3d8,0,if(cols==40)0x08 else 0x09,true);for(0..25)|y|try row(&f,@intCast(y));try capture(&f,if(cols==40)"40-intensity"else "80-intensity",1);}}
test "cursor sampler preserves all256 nativeFLAGS guest PIT FILE UCI and no guest retirement on success and failure"{
 var f=try text();defer f.deinit();try util.video(&f,1,0,0,0);try time(&f,19912*7,0);const names=[_][2][]const u8{.{"dos64_pit_state_start","dos64_pit_state_end"},.{"dos64_files_state_start","dos64_files_state_end"},.{"dos64_uci_state_start","dos64_uci_state_end"},.{"dos64_guest","dos64_mailbox_end"}};var bytes:[1024]u8=undefined;var n:usize=0;for(names)|pair|{const a=try f.symbol(pair[0]);const b=try f.symbol(pair[1]);for(a..b)|at|{bytes[n]=f.peek(@intCast(at));n+=1;}}const retired=f.word(try f.symbol("dos64_cpu_instructions"));for(0..256)|flags|{f.initial_status=@intCast(flags);for([_]bool{true,false})|ok|{f.poke(try f.symbol("hdb_extension_ready"),if(ok)0xa5 else 0);const r=try f.call("dos64_cga_cursor_sample",100000);try std.testing.expectEqual(@as(u8,@intFromBool(!ok)),r.p&1);try std.testing.expectEqual(@as(u8,@truncate(flags))&0xce,r.p&0xce);var i:usize=0;for(names)|pair|{const a=try f.symbol(pair[0]);const b=try f.symbol(pair[1]);for(a..b)|at|{try std.testing.expectEqual(bytes[i],f.peek(@intCast(at)));i+=1;}}try std.testing.expectEqual(retired,f.word(try f.symbol("dos64_cpu_instructions")));}}
}
test "unsupported direct start invertedshape and failedREU retain truthful cache and refuse before full output while hidden shape is harmless"{
 var f=try text();defer f.deinit();try util.video(&f,1,0,0,0);try time(&f,0,0);try sample(&f);const rr=try f.symbol("dos64_cga_registers");const r=try f.symbol("dos64_render_text_request");for(0..2)|kind|{try cursor(&f,0,if(kind==1)7 else 6,if(kind==1)6 else 7);f.poke(rr+13,if(kind==0)1 else 0);for(0..8000)|i|f.poke(0x6000+@as(u16,@intCast(i)),0x96);for(0..1000)|i|f.poke(0x4000+@as(u16,@intCast(i)),0x69);f.poke(r,0);f.poke(r+1,1);try std.testing.expectEqual(@as(u8,1),(try f.call("dos64_overlay_render_text_row",2000000)).p&1);try std.testing.expectEqual(@as(u8,3),f.peek(r+4));for(0..8000)|i|try std.testing.expectEqual(@as(u8,0x96),f.peek(0x6000+@as(u16,@intCast(i))));for(0..1000)|i|try std.testing.expectEqual(@as(u8,0x69),f.peek(0x4000+@as(u16,@intCast(i))));}try cursor(&f,0,0x3f,0);try whole(&f,40,null,0,7);try cursor(&f,0,6,7);try util.acquire(&f,4);try util.release(&f);c.dos64_reu_fail_after(f.machine,0,0);try std.testing.expectEqual(@as(u8,1),(try f.call("dos64_cga_cursor_sample",100000)).p&1);try std.testing.expectEqual(@as(u8,255),f.peek(try f.symbol("dos64_cursor_phase_valid")));try std.testing.expectEqual(@as(u8,0),f.peek(try f.symbol("dos64_cursor_field_phase")));try std.testing.expectEqual(@as(u8,0),f.peek(try f.symbol("dos64_overlay_busy")));
}
test "existing native workflow bitmap oracle requires captured phase and exact physical halfcursor rather than disabling it"{
 var f=try text();defer f.deinit();try util.video(&f,3,0,0,0);try time(&f,0,0);try sample(&f);try cursor(&f,7,5,7);var bda:[256]u8=undefined;for(&bda,0..)|*v,i|v.*=try util.busRead(&f,0x400+@as(u32,@intCast(i)));const oracle=try @import("cga_cursor_expected.zig").Cursor.capture(&f,&bda);try std.testing.expectEqual(@as(u8,15),oracle.mask(80,0,3,5));try std.testing.expectEqual(@as(u8,0),oracle.mask(80,0,3,4));try std.testing.expectEqual(@as(u8,0),oracle.mask(80,0,4,5));
